28	export const BENNY_RIDE_OFFSET = 0.55;
29	/** Benny's outer (fur) radius near the waterline: skin 0.7 + fur 0.12 + lower-body bulge (benny/build.ts BENNY_DIMS) */
30	const BENNY_OUTER_R = 0.86;
31	
32	export interface WaterControls {
33	  /** 02 tumble: spinning water shell on the Drum A wall (0..1) */
34	  drumSwirl: number;
35	  /** Drum A swell size: 0 calm (01) .. 1 spin cycle (02) */
36	  drumAgitation: number;
37	  /** 11 outro: stream drains away (0..1) and leftover puddles appear */
