41	export interface WaterSystem {
42	  group: THREE.Group;
43	  /** call every frame; focusS = Benny's arc-length (for pooling/LOD of bubbles & foam) */
44	  update(time: number, dt: number, focusS: number, camera: THREE.Camera): void;
45	  /** height of the animated water surface above the course centreline frame at (s, lateral) */
46	  surfaceHeight(s: number, lateral: number, time: number): number;
47	  /** spray/wake at Benny: call each frame while riding */
48	  wake(pos: THREE.Vector3, forward: THREE.Vector3, right: THREE.Vector3, speed: number, dt: number): void;
49	  splash(pos: THREE.Vector3, up: THREE.Vector3, strength: number): void;
50	  /** cinematic controls */
51	  controls: WaterControls;
52	  /** sub-systems (for visibility overrides / debugging) */
53	  parts: Record<string, THREE.Object3D>;
54	  /** live stats for perf reporting */
55	  stats(): { instances: number; bubbles: number; smallBubbles: number; sprayCapacity: number };
56	}
