58	const smooth = (a: number, b: number, x: number) => {
59	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
60	  return t * t * (3 - 2 * t);
61	};
62	
63	export function createWater(course: Course, opts: { quality?: 'high' | 'low' } = {}): WaterSystem {
64	  const quality = opts.quality ?? 'high';
65	  const group = new THREE.Group();
66	  group.name = 'water_system';
67	
68	  const drainMark = course.marks['02_drain'] ?? course.stage('02').s1 - 2;
69	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08'), st09 = course.stage('09');
70	  const ribbonS0 = drainMark - 1;
71	  const ribbon = createRibbon(course, { s0: ribbonS0, s1: course.length, quality });
72	  // open the funnel where the 04 slide tube leaves the basin (the course exits the spiral at
73	  // r≈2.8, just outside the drain hole, and the slide then runs beneath the funnel surface)
74	  const cutPts: THREE.Vector3[] = [];
75	  for (let i = 0; i < 8; i++) {
76	    const s = st04.s0 - 3 + (i / 7) * 34;
77	    const f = course.sample(s);
78	    cutPts.push(f.pos.clone().addScaledVector(f.up, 1.2));
79	  }
80	  const whirl = createWhirlpool(quality, { points: cutPts, radius: Math.max(3.6, course.stage('04').tube * 0.85) });
81	  const drum = createDrumWater(quality);
82	  const wave = createFinalWave(course, quality);
83	  const puddles = createPuddles();
84	  const foam = createFoam(course, { s0: ribbonS0, s1: course.length, quality, height: (s, lat, t) => ribbon.heightAt(s, lat, t) });
85	  const bubbles = createBubbles(course, { quality, sStart: ribbonS0 });
86	  const spray = createSpray(quality);
87	  const crown = createRiderSplash(quality);
88	  group.add(ribbon.mesh, whirl.mesh, drum.group, wave.mesh, puddles.group, foam.group, bubbles.group, spray.points, crown.mesh);
89	
90	  const parts: Record<string, THREE.Object3D> = { ribbon: ribbon.mesh, whirlpool: whirl.mesh, drum: drum.group, drumSwirl: drum.swirl, finalWave: wave.mesh, puddles: puddles.group, foam: foam.group, foamBerm: foam.berm, foamRafts: foam.rafts, foamFlank: foam.flank, bubbles: bubbles.group, bubblesSmall: bubbles.small, bubblesBig: bubbles.big, spray: spray.points, splashCrown: crown.mesh };
91	  const controls: WaterControls = { drumSwirl: 0, drumAgitation: 0, outro: 0 };
92	  // QA: ?waterhide=crown,spray,bubbles,foam,foamBerm,ribbon … hides water parts (isolation captures)
93	  const qaHide = typeof location !== 'undefined' ? (new URLSearchParams(location.search).get('waterhide') ?? '').split(',').filter(Boolean) : [];
94	  /** `waterhide=ribbonWake`: keep the ribbon but switch off its Benny contact/wake block */
95	  const qaNoRibbonWake = qaHide.includes('ribbonWake');
96	  let focus = 0;
97	  let curTime = 0;
98	  const tmpV = new THREE.Vector3();
99	  const tmpV2 = new THREE.Vector3();
100	  const tmpV3 = new THREE.Vector3();
101	  // spray fan scratch (no per-frame allocation)
102	  const sprP = new THREE.Vector3();
103	  const sprV = new THREE.Vector3();
104	  const back = new THREE.Vector3();
105	  const lastWake = new THREE.Vector3();
106	  const riderVel = new THREE.Vector3();
107	  let lastWakeT = -1;
108	  // seeded RNG for the spray: re-seeded whenever Benny jumps (checkpoint / respawn), so QA frames are
109	  // deterministic and comparable between runs
110	  let seed = 0x5eed;
111	  const rand = () => {
112	    seed = (seed + 0x6d2b79f5) >>> 0;
113	    let t = seed;
114	    t = Math.imul(t ^ (t >>> 15), t | 1);
115	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
116	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
117	  };
118	  const rnd = (a: number, b: number) => a + rand() * (b - a);
119	  let lastFocusSeed = -1e9;
120	  let qaCamera: THREE.Camera | null = null;
121	
122	  /** 0 = ribbon fully shown, 1 = whirlpool surface takes over (mirrors the ribbon vertex shader) */
123	  const whirlBlend = (s: number) => smooth(st03.s0 + 0.5, st03.s0 + 3.5, s) * (1 - smooth(st04.s0 - 9, st04.s0 - 1.5, s));
124	
125	  const surfaceHeight = (s: number, lateral: number, t: number): number => {
126	    if (s < ribbonS0) {
127	      // Drum A: absolute swell height relative to the course point
128	      const p = course.pointAt(s, lateral, 0, tmpV);
129	      const up = course.sample(s).up;
130	      return (drum.heightAt(p.x, p.z, t) - p.y) / Math.max(0.3, up.y);
131	    }
132	    const hr = ribbon.heightAt(s, lateral, t);
133	    const k = whirlBlend(s);
134	    if (k <= 0) return hr;
135	    const f = course.sample(s);
136	    const p = tmpV.copy(f.pos).addScaledVector(f.right, lateral);
137	    const b = WORLD.basin;
138	    const r = Math.hypot(p.x - b.center.x, p.z - b.center.z);
139	    const yW = funnelY(r) + FUNNEL_LIFT + whirlpoolHeight(p.x, p.z, t);
140	    const hw = (yW - p.y) / Math.max(0.3, f.up.y);
141	    return hr * (1 - k) + hw * k;
142	  };
143	
144	  // QA (?qa=1): window.__waterQA() reports what the VFX put on screen (bubble sizes/positions, foam
145	  // rafts) for the capture scripts; read-only, nothing is allocated unless it is called
146	  if (typeof window !== 'undefined' && new URLSearchParams(location.search).has('qa')) {
147	    (window as unknown as { __waterQA: () => unknown }).__waterQA = () => {
148	      const cam = qaCamera as THREE.PerspectiveCamera | null;
149	      if (!cam) return null;
150	      const w = window.innerWidth, h = window.innerHeight;
151	      return { bubbles: bubbles.qaScreen(cam, w, h), rafts: foam.qaRafts(), fanStrength: crown.uniforms.uStrength.value, waterlineR: ribbon.uniforms.uBennyR.value };
152	    };
153	  }
154	
155	  return {
156	    group,
157	    controls,
158	    parts,
159	    surfaceHeight,
160	    stats: () => ({ instances: foam.instanceCount, bubbles: bubbles.counts.big, smallBubbles: bubbles.counts.small, sprayCapacity: spray.capacity }),
161	    update(time, dt, focusS, camera) {
162	      if (Math.abs(focusS - lastFocusSeed) > 25) seed = 0x5eed ^ Math.round(focusS * 16);
163	      lastFocusSeed = focusS;
164	      qaCamera = camera;
165	      focus = focusS;
166	      curTime = time;
167	      ribbon.uniforms.uTime.value = time;
168	      whirl.uniforms.uTime.value = time;
169	      drum.uniforms.uTime.value = time;
170	      drum.uniforms.uAgitation.value = controls.drumAgitation;
171	      drum.swirlUniforms.uSwirl.value = controls.drumSwirl;
172	      drum.swirl.visible = controls.drumSwirl > 0.001;
173	      wave.uniforms.uTime.value = time;
174	      puddles.uniforms.uTime.value = time;
175	      puddles.uniforms.uAmount.value = controls.outro;
176	      (ribbon.uniforms.uOutro.value as THREE.Vector2).x = controls.outro;
177	      puddles.group.visible = controls.outro > 0.001;
178	      // region visibility (perf): only what the camera around focusS can see
179	      drum.group.visible = focusS < st03.s0 + 12;
180	      whirl.mesh.visible = focusS > drainMark - 8 && focusS < st04.s0 + 45;
181	      wave.mesh.visible = focusS > st08.s0 - 25;
182	      // when Benny is off the ribbon (drum / whirlpool), no ribbon wake
183	      if (focusS < ribbonS0 || whirlBlend(focusS) > 0.5) (ribbon.uniforms.uBenny.value as THREE.Vector3).z = 0;
184	      foam.update(time, dt, focusS, controls.outro, camera);
185	      bubbles.update(time, dt, focusS, camera, 1 - 0.7 * controls.outro);
186	      // crest spray off the final wave
187	      if (wave.mesh.visible && focusS > st09.s0 - 20 && focusS < st09.s1 + 20 && controls.outro < 0.5) {
188	        const n = quality === 'high' ? 3 : 1;
189	        for (let i = 0; i < n; i++) {
190	          const c = wave.crest[(rand() * wave.crest.length) | 0];
191	          if (!c) break;
192	          const f = course.sample(Math.min(course.length, Math.max(0, focusS)));
193	          tmpV2.copy(f.right).multiplyScalar(rnd(1, 3.5)).addScaledVector(f.up, rnd(1.5, 4)).addScaledVector(f.tan, rnd(-1, 2));
194	          spray.emit(c, tmpV2, rnd(0.08, 0.2), rnd(0.5, 1.0));
195	        }
196	      }
197	      spray.update(dt, camera);
198	      crown.update(time, dt);
199	      for (const k of qaHide) { const o = parts[k]; if (o) o.visible = false; }
200	    },
201	    wake(pos, forward, right, speed, dt) {
202	      // Benny's arc length / lateral from his actual position (focus lags one frame)
203	      const f0 = course.sample(Math.max(0, focus));
204	      const d = tmpV3.copy(pos).sub(f0.pos);
205	      const s = Math.min(course.length, Math.max(0, focus + d.dot(f0.tan)));
206	      const f = course.sample(s);
207	      d.copy(pos).sub(f.pos);
208	      const lateral = d.dot(f.right);
209	      // pos = Benny's real body centre (Game.ts passes it AFTER the runtime's ride lift). The waterline
210	      // radius is the chord of the fluffy ball at the water surface, so the contact foam, the crown and
211	      // the ribbon wake hug his actual footprint. (Deriving the radius from `above / BENNY_RIDE_OFFSET`
212	      // made it grow with the lift and drew a white contact band ~2x wider than the body.)
213	      const above = d.dot(f.up) - surfaceHeight(s, lateral, curTime);
214	      const waterlineR = Math.sqrt(Math.max(BENNY_OUTER_R * BENNY_OUTER_R - above * above, (0.35 * BENNY_OUTER_R) ** 2));
215	      const strength = Math.min(1, speed / 8);
216	      if (s >= ribbonS0 && whirlBlend(s) < 0.5 && !qaNoRibbonWake) {
217	        (ribbon.uniforms.uBenny.value as THREE.Vector3).set(s, lateral, strength);
218	        ribbon.uniforms.uBennyR.value = waterlineR;
219	      }
220	      // 3D V spray fans thrown back and outward from the waterline (ref 05)
221	      const center = tmpV.copy(pos).addScaledVector(f.up, -above);
222	      crown.place(center, forward, f.up, waterlineR, strength);
223	      // Benny's measured velocity: droplets inherit it so the fan stays attached to him instead of
224	      // trailing 4-6 units back toward the chase camera (the old white spots at the frame bottom).
225	      // QA checkpoints hold him still, so the measured velocity is 0 there as well.
226	      if (lastWakeT >= 0 && dt > 1e-4 && lastWake.distanceToSquared(pos) < 9) riderVel.copy(pos).sub(lastWake).divideScalar(dt);
227	      else riderVel.set(0, 0, 0);
228	      lastWake.copy(pos);
229	      lastWakeT = curTime;
230	      // droplets thrown off the two streak fans: rooted on the flanks at the waterline and flying
231	      // back-outward along the same jet directions as riderSplash.ts (FAN), a short hop above the water
232	      // (ref 05: fine 3–12 px droplets all round the fans, a few flung up beside the body)
233	      const rate = (quality === 'high' ? 150 : 55) * strength;
234	      const n = Math.min(14, Math.floor(rate * dt + rand()));
235	      const up = tmpV2.copy(f.up);
236	      back.copy(forward).multiplyScalar(-1);
237	      for (let i = 0; i < n; i++) {
238	        const side = rand() < 0.5 ? -1 : 1;
239	        const a = rand();
240	        const thR = FAN.root0 + (FAN.root1 - FAN.root0) * a;
241	        const phi = FAN.dir0 + (FAN.dir1 - FAN.dir0) * a + rnd(-0.12, 0.12);
242	        const t0 = rnd(0.1, 0.55); // leave the jet part-way along it
243	        const rootR = Math.max(waterlineR, FAN.rootMin) * 0.95;
244	        sprP.copy(center)
245	          .addScaledVector(right, side * (Math.sin(thR) * rootR + Math.sin(phi) * t0 * 0.9))
246	          .addScaledVector(back, Math.cos(thR) * rootR + Math.cos(phi) * t0 * 0.9)
247	          .addScaledVector(up, rnd(0.04, 0.16));
248	        const sp = rnd(1.1, 2.6);
249	        sprV.copy(riderVel).addScaledVector(right, side * Math.sin(phi) * sp).addScaledVector(back, Math.cos(phi) * sp).addScaledVector(up, rnd(1.2, 3.0));
250	        spray.emit(sprP, sprV, rnd(0.018, 0.05), rnd(0.3, 0.6));
251	      }
252	      // the 05 flank banks (foam.ts) keep clear of Benny's real waterline position
253	      foam.rider(s, lateral, strength);
254	    },
255	    splash(pos, up, strength) {
256	      const n = Math.round(30 * strength * (quality === 'high' ? 1 : 0.5));
257	      for (let i = 0; i < n; i++) {
258	        const dir = sprV.set(rnd(-1, 1), 0, rnd(-1, 1)).normalize().multiplyScalar(rnd(1, 4) * strength);
259	        dir.addScaledVector(up, rnd(3, 7) * strength);
260	        spray.emit(pos, dir, rnd(0.06, 0.16), rnd(0.5, 1.1));
261	      }
262	    },
263	  };
264	}
