1	/**
2	 * Iridescent soap bubbles.
3	 *  - big bubbles: instanced camera-facing sphere IMPOSTORS (2 triangles each) with an analytic
4	 *    thin-film shader: saturated magenta/cyan film, crisp outline, tinted interior, white window
5	 *    highlights (ref 05). The on-screen diameter is capped (uMaxPx) and bubbles fade out close to the
6	 *    camera, so a bubble can never become a giant occluding sphere.
7	 *  - small bubbles: one THREE.Points draw of tiny ring-sprite bubbles.
8	 * Ride (03–10): bubbles live only at the SIDES of the stream, over the foam banks and the lower
9	 * walls (ref 05: ≈18 large 25–65 px + ≈25 small, none over the path or Benny). Drum A (01–02):
10	 * free-floating in the drum volume as before.
11	 * Pooled (fixed arrays, no per-frame allocation); respawned ahead when Benny passes them.
12	 */
13	import * as THREE from 'three';
14	import { type Course, WORLD } from '../world/course';
15	import { BERM_OUT } from './foam';
16	import { coreLateral } from './waterRibbon';
17	import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
18	
19	const BIG_VERT = /* glsl */ `
20	attribute float aSeed;
21	uniform float uFocal;   // pixels per unit at depth 1 (viewport height / (2 tan(fov/2)))
22	uniform float uMaxPx;   // cap on the on-screen diameter
23	uniform float uNear;    // fade-out distance from the camera
24	varying vec2 vP;
25	varying float vSeed;
26	varying float vFade;
27	varying float vPx;
28	#include <fog_pars_vertex>
29	void main() {
30	  vec4 c = modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
31	  float r = length((instanceMatrix * vec4(1.0, 0.0, 0.0, 0.0)).xyz);
32	  vec4 cv = viewMatrix * c;
33	  float depth = max(-cv.z, 0.01);
34	  float px = 2.0 * r * uFocal / depth;
35	  float k = min(1.0, uMaxPx / max(px, 1e-3));
36	  r *= k;
37	  vPx = px * k;
38	  vFade = smoothstep(uNear, uNear * 1.8, depth) * step(0.0005, r);
39	  vP = position.xy;
40	  vSeed = aSeed;
41	  vec4 mvPosition = cv + vec4(position.xy * r, 0.0, 0.0);
42	  gl_Position = projectionMatrix * mvPosition;
43	  #include <fog_vertex>
44	}
45	`;
46	const BIG_FRAG = /* glsl */ `
47	uniform float uTime;
48	varying vec2 vP;
49	varying float vSeed;
50	varying float vFade;
51	varying float vPx;
52	#include <fog_pars_fragment>
53	${NOISE_GLSL}
54	void main() {
55	  float d2 = dot(vP, vP);
56	  if (d2 > 1.0 || vFade < 0.01) discard;
57	  float d = sqrt(d2);
58	  float z = sqrt(1.0 - d2);
59	  float f = 1.0 - z;                                   // 0 centre → 1 silhouette
60	  // swirling thin film: magenta / violet / cyan bands with a little gold (ref 05)
61	  float sw = vnoise(vP * 2.2 + vec2(uTime * 0.3 + vSeed * 13.0, vSeed * 7.0));
62	  float hue = f * 0.85 + sw * 0.75 + vP.x * 0.25 - vP.y * 0.2 + vSeed;
63	  vec3 film = iridescent(hue);
64	  film = vec3(film.r, film.g * 0.55 + 0.1, min(1.0, film.b * 1.1 + 0.1));   // less green
65	  film *= 0.74;                                        // stay under the tone-mapping knee: saturated
66	  float rim = smoothstep(0.5, 0.97, d);
67	  float edge = smoothstep(0.88, 0.97, d) * (1.0 - smoothstep(0.975, 1.0, d));
68	  // window highlights: a soft bright pane up-left, a small one down-right, sparkle dots on the rim
69	  vec2 q1 = (vP - vec2(-0.36, 0.42)) * vec2(2.2, 3.0);
70	  float hl = exp(-dot(q1, q1) * 2.2) * 1.2;
71	  vec2 q2 = vP - vec2(0.42, -0.45);
72	  hl += exp(-dot(q2, q2) * 55.0) * 0.7;
73	  float ang = atan(vP.y, vP.x);
74	  hl += smoothstep(0.8, 0.93, d) * (1.0 - smoothstep(0.95, 1.0, d)) * pow(max(0.0, sin(ang * 4.0 + vSeed * 31.0)), 30.0) * 0.9;
75	  // tiny bubbles: keep only the ring + one glint (no shimmering detail below ~14 px)
76	  float small = 1.0 - smoothstep(10.0, 22.0, vPx);
77	  hl *= 1.0 - 0.5 * small;
78	  vec3 col = film * (0.55 + 0.75 * rim) + vec3(1.0) * edge * 0.45 + vec3(1.05) * hl;
79	  float a = 0.14 + 0.1 * sw + rim * 0.6 + edge * 0.35 + hl;
80	  gl_FragColor = vec4(col, clamp(a, 0.0, 0.95) * vFade);
81	  ${FRAG_TAIL}
82	}
83	`;
