85	const PT_VERT = /* glsl */ `
86	attribute float aSize;
87	attribute float aSeed;
88	uniform float uScale;
89	uniform float uMaxPx;
90	varying float vSeed;
91	varying float vPx;
92	#include <fog_pars_vertex>
93	void main() {
94	  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
95	  float px = aSize * uScale / max(-mvPosition.z, 0.01);
96	  gl_PointSize = aSize > 0.0 ? clamp(px, 2.0, uMaxPx) : 0.0;
97	  vPx = gl_PointSize;
98	  vSeed = aSeed;
99	  gl_Position = projectionMatrix * mvPosition;
100	  #include <fog_vertex>
101	}
102	`;
103	const PT_FRAG = /* glsl */ `
104	uniform float uTime;
105	varying float vSeed;
106	varying float vPx;
107	#include <fog_pars_fragment>
108	${NOISE_GLSL}
109	void main() {
110	  vec2 c = gl_PointCoord - 0.5;
