115	  irid = vec3(irid.r, irid.g * 0.55 + 0.1, irid.b) * 0.8;
116	  float hl = smoothstep(0.26, 0.0, length(c - vec2(-0.17, -0.17)));
117	  vec3 col = mix(vec3(1.0), irid, 0.6) * ring * 1.2 + vec3(1.0) * hl * 1.4 + irid * 0.25;
