119	  float alpha = clamp(ring * 0.8 + hl + 0.12, 0.0, 1.0) * (0.35 + 0.65 * smoothstep(3.0, 8.0, vPx));
120	  gl_FragColor = vec4(col, alpha);
121	  ${FRAG_TAIL}
122	}
123	`;
