145	// seeded RNG: re-seeded on every respawn-all (checkpoint jump), so QA frames are deterministic
146	let rngState = 0x0b0b;
147	function rand() {
148	  rngState = (rngState + 0x6d2b79f5) >>> 0;
149	  let t = rngState;
150	  t = Math.imul(t ^ (t >>> 15), t | 1);
151	  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
152	  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
153	}
154	function rnd(a: number, b: number) {
155	  return a + rand() * (b - a);
156	}
157	
158	/** ride counts (visible at once in a 05-like frame) and caps, per quality tier */
159	const RIDE = {
160	  // wave 4 (user): ≈15–20 larger soap bubbles at the sides, only a few small ones
161	  high: { big: 19, small: 12 },
162	  low: { big: 14, small: 8 },
163	};
164	/** half width (NDC x) of the no-bubble lane around the projected cyan core / coin line */
165	const CORE_LANE = 0.19;
166	const CORE_N = 24;
167	/** ride big bubbles: target on-screen diameter range (px in the 864×1536 frame), ref 05 ≈25–65 px */
168	const BIG_PX: [number, number] = [25, 65];
169	/** max on-screen diameters (px at the capture/device resolution) */
170	const MAX_PX_RIDE = 66;
171	const MAX_PX_DRUM = 120;
172	const MAX_PX_SMALL = 22;
173	
174	export function createBubbles(course: Course, opts: { quality: 'high' | 'low'; sStart: number }): BubbleSystem {
175	  const quality = opts.quality;
176	  const ride = RIDE[quality];
177	  const nBig = Math.max(ride.big, 16);
178	  const nSmall = quality === 'high' ? 170 : 80; // drum A keeps its fizz; the ride uses ride.small
179	  const group = new THREE.Group();
180	  group.name = 'bubbles';
181	  const dA = WORLD.drumA;
182	  const drumEnd = course.marks['02_drain'] ?? course.stage('03').s0;
183	
184	  // ---- big (impostors) ----
185	  const quad = new THREE.PlaneGeometry(2, 2);
186	  const seeds = new Float32Array(nBig).map(() => rand());
187	  quad.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seeds, 1));
188	  const bigUniforms = withFog({ uTime: { value: 0 }, uFocal: { value: 1000 }, uMaxPx: { value: MAX_PX_RIDE }, uNear: { value: 3.2 } });
189	  const big = new THREE.InstancedMesh(
190	    quad,
191	    new THREE.ShaderMaterial({ uniforms: bigUniforms, vertexShader: BIG_VERT, fragmentShader: BIG_FRAG, fog: true, transparent: true, depthWrite: false }),
192	    nBig,
193	  );
194	  big.name = 'bubbles_big';
195	  big.frustumCulled = false;
196	  big.renderOrder = 5;
197	  group.add(big);
198	
199	  // ---- small ----
200	  const sPos = new Float32Array(nSmall * 3);
201	  const sSize = new Float32Array(nSmall);
202	  const sSeed = new Float32Array(nSmall).map(() => rand());
203	  const pGeo = new THREE.BufferGeometry();
204	  pGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3).setUsage(THREE.DynamicDrawUsage));
205	  pGeo.setAttribute('aSize', new THREE.BufferAttribute(sSize, 1).setUsage(THREE.DynamicDrawUsage));
206	  pGeo.setAttribute('aSeed', new THREE.BufferAttribute(sSeed, 1));
207	  const ptUniforms = withFog({ uTime: { value: 0 }, uScale: { value: 600 }, uMaxPx: { value: MAX_PX_SMALL } });
208	  const small = new THREE.Points(
209	    pGeo,
210	    new THREE.ShaderMaterial({ uniforms: ptUniforms, vertexShader: PT_VERT, fragmentShader: PT_FRAG, fog: true, transparent: true, depthWrite: false }),
211	  );
212	  small.name = 'bubbles_small';
213	  small.frustumCulled = false;
214	  small.renderOrder = 4;
215	  group.add(small);
216	
217	  const mk = (): BubbleState => ({ s: 0, pos: new THREE.Vector3(), vel: new THREE.Vector3(), size: 1, phase: 0, age: 0, life: 1 });
218	  const bigS: BubbleState[] = Array.from({ length: nBig }, mk);
219	  const smallS: BubbleState[] = Array.from({ length: nSmall }, mk);
220	
221	  const tmp = new THREE.Vector3();
222	  const tmp2 = new THREE.Vector3();
223	  const tmp3 = new THREE.Vector3();
224	  /** camera basis of the current frame (screen-space placement / exclusion) */
225	  const view = { pos: new THREE.Vector3(), dir: new THREE.Vector3(0, 0, -1), right: new THREE.Vector3(1, 0, 0), up: new THREE.Vector3(0, 1, 0), tanV: 0.6, tanH: 0.34, inv: new THREE.Matrix4(), ok: false };
226	  /**
227	   * 1 = fine, 0 = in the no-bubble corridor (stream centre: Benny, splash, coin line), -1 = out of
228	   * the frame / too close to the camera. NDC from the camera basis; `r` (world radius) widens the
229	   * corridor so a bubble's rim never overlaps Benny either.
230	   */
231	  const allowed = (p: THREE.Vector3, r = 0): number => {
232	    if (!view.ok) return 1;
233	    const v = tmp3.copy(p).applyMatrix4(view.inv);
234	    const depth = -v.z;
235	    if (depth < 2.5) return -1;
236	    const xn = v.x / (depth * view.tanH), yn = v.y / (depth * view.tanV);
237	    if (Math.abs(xn) > 1.12 || yn < -1.12 || yn > 1.1) return -1;
238	    if (yn > 0.62) return 0; // upper tube / HUD: keep clear (ref 05 has none there)
239	    const rN = r / (depth * view.tanH);
240	    const corridor = yn < 0.1 ? 0.47 : 0.3;
241	    if (Math.abs(xn) - rN < corridor) return 0;
242	    // the route ahead (cyan core + coin line) winds off the screen centre in 05: keep a lane clear
243	    // around its projection at this screen row (the nearest coin sits at x≈640 in the 05 frame)
244	    if (coreN > 1 && yn <= coreY[coreN - 1] && yn >= coreY[0] - 0.4) {
245	      let i = 0;
246	      while (i < coreN - 2 && coreY[i + 1] < yn) i++;
247	      const t = Math.min(1, Math.max(0, (yn - coreY[i]) / Math.max(1e-4, coreY[i + 1] - coreY[i])));
248	      const xc = coreX[i] + (coreX[i + 1] - coreX[i]) * t;
249	      if (Math.abs(xn - xc) - rN < CORE_LANE) return 0;
250	    }
251	    return 1;
252	  };
253	  /** projected core line (NDC), sorted by screen y (bottom → top), rebuilt every frame in update() */
254	  const coreX = new Float32Array(CORE_N), coreY = new Float32Array(CORE_N);
255	  let coreN = 0;
256	  /** pixels per unit at depth 1 and the frame-height scale of the current frame (set in update) */
257	  let focalNow = 1000;
258	  let pxKNow = 1;
259	  const f0 = { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
260	  const fi = { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
261	  const ray = new THREE.Vector3();
262	  const spawn = (b: BubbleState, focusS: number, isBig: boolean, initial: boolean) => {
263	    b.phase = rand() * 6.28;
264	    b.age = initial ? rnd(0.5, 3) : 0;
265	    b.life = rnd(7, 15);
266	    if (focusS < drumEnd) {
267	      // Drum A volume: big bubbles floating around the drum, small ones near the water
268	      const th = rnd(0, Math.PI * 2);
269	      const r = Math.sqrt(rand()) * (dA.radius - 0.9);
270	      const x = dA.center.x + Math.cos(th) * r;
271	      const y = isBig ? rnd(dA.waterY - 0.2, dA.center.y + dA.radius * 0.7) : rnd(dA.waterY + 0.05, dA.waterY + 1.6);
272	      const z = rnd(dA.zBack + 0.6, dA.zDoor - 0.4);
273	      b.pos.set(x, y, z);
274	      b.s = focusS;
275	      b.vel.set(rnd(-0.15, 0.15), rnd(0.05, 0.25), rnd(-0.1, 0.1));
276	      b.size = isBig ? (rand() < 0.25 ? rnd(0.45, 0.85) : rnd(0.16, 0.42)) : rnd(0.05, 0.16);
277	      return;
278	    }
279	    // ---- ride: at the SIDES of the frame only (over the foam banks / outer water), never over the
280	    // stream corridor where Benny, his splash and the coin line are (ref 05: ≈18 large 25–65 px and
281	    // ≈25 small bubbles between the bank tops at y≈540 and Benny's splash at y≈1290, x at the sides).
282	    // Placed in SCREEN space so it holds for any camera: pick a side screen point, find where its view
283	    // ray meets the water, and float the bubble somewhere between the camera and that point. Size is
284	    // chosen from the wanted on-screen diameter at that depth. Respawns start further up the frame
285	    // (far, small) and grow naturally as Benny rides towards them.
286	    course.sample(Math.max(opts.sStart, focusS), f0);
287	    const side = rand() < 0.5 ? -1 : 1;
288	    const H = 1536;
289	    let D = 6;
290	    for (let attempt = 0; attempt < 5; attempt++) {
291	      const yPx = initial ? rnd(530, 1290) : rnd(530, 820);
292	      const yn = 1 - (2 * yPx) / H;
293	      const xn = side * rnd(isBig ? 0.55 : 0.5, 0.97);
294	      ray.copy(view.dir).addScaledVector(view.right, xn * view.tanH).addScaledVector(view.up, yn * view.tanV);
295	      // distance (along the view axis) to the water plane under Benny
296	      const den = ray.dot(f0.up);
297	      let Dw = den < -1e-3 ? tmp2.copy(f0.pos).sub(view.pos).dot(f0.up) / den : 40;
298	      Dw = Math.min(40, Math.max(3, Dw));
299	      D = Math.max(3.9, Dw * rnd(isBig ? 0.55 : 0.6, 0.92));
300	      // keep inside the tube: shorten the ray while the point is beyond the bank top
301	      let s = focusS;
302	      for (let k = 0; k < 4; k++) {
303	        tmp.copy(view.pos).addScaledVector(ray, D);
304	        s = focusS;
305	        for (let it = 0; it < 2; it++) {
306	          course.sample(Math.min(course.length, Math.max(opts.sStart, s)), fi);
307	          s += tmp2.copy(tmp).sub(fi.pos).dot(fi.tan);
308	        }
309	        s = Math.min(course.length - 0.3, Math.max(opts.sStart, s));
310	        course.sample(s, fi);
311	        const hw = course.widthAt(s) / 2;
312	        const lat = tmp2.copy(tmp).sub(fi.pos).dot(fi.right);
313	        if (Math.abs(lat) <= hw + BERM_OUT + 0.3) break;
314	        D *= 0.85;
315	      }
316	      // never under the water / inside the bank foam
317	      const above = tmp2.copy(tmp).sub(fi.pos).dot(fi.up);
318	      if (above < 0.15) tmp.addScaledVector(fi.up, 0.15 - above);
319	      b.pos.copy(tmp);
320	      b.s = s;
321	      const flow = course.prop(s, 'speed') * (isBig ? 0.1 : 0.2);
322	      b.vel.copy(fi.tan).multiplyScalar(flow).addScaledVector(fi.up, rnd(0.04, 0.16));
323	      const depth = Math.max(2.5, tmp2.copy(b.pos).sub(view.pos).dot(view.dir));
324	      if (isBig) {
325	        const px = BIG_PX[0] + (BIG_PX[1] - BIG_PX[0]) * Math.pow(rand(), 1.25);
326	        b.size = THREE.MathUtils.clamp((px * pxKNow * depth) / (2 * focalNow), 0.05, 0.5);
327	      } else {
328	        const px = 6 + 14 * Math.pow(rand(), 1.4);
329	        b.size = THREE.MathUtils.clamp((px * pxKNow * depth) / focalNow, 0.02, 0.3); // point-sprite diameter
330	      }
331	      if (allowed(b.pos, isBig ? b.size : b.size * 0.5) > 0) break;
332	    }
333	  };
334	
335	  let lastFocus = -1e9;
336	  const lastCam = new THREE.Vector3(1e9, 1e9, 1e9);
337	  const tmpM = new THREE.Matrix4();
338	  const one = new THREE.Quaternion();
339	  const scl = new THREE.Vector3();
340	
341	  const qv = new THREE.Vector3();
342	  const qm = new THREE.Matrix4();
343	  const qs = new THREE.Vector3();
344	  return {
345	    group,
346	    big,
347	    small,
348	    counts: { big: nBig, small: nSmall },
349	    qaScreen(camera, w, h) {
350	      const out = { big: [] as number[][], small: [] as number[][] };
351	      if (!camera.isPerspectiveCamera) return out;
352	      const focal = h / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
353	      const maxPx = (bigUniforms.uMaxPx.value as number) * (h / (window.innerHeight * Math.min(2, window.devicePixelRatio || 1)));
354	      for (let i = 0; i < nBig; i++) {
355	        big.getMatrixAt(i, qm);
356	        qs.setFromMatrixScale(qm);
357	        if (qs.x < 1e-4) continue;
358	        qv.setFromMatrixPosition(qm);
359	        const depth = qv.clone().applyMatrix4(camera.matrixWorldInverse).z * -1;
360	        if (depth < 0.1) continue;
361	        qv.project(camera);
362	        if (Math.abs(qv.x) > 1.05 || Math.abs(qv.y) > 1.05) continue;
363	        out.big.push([Math.round((qv.x * 0.5 + 0.5) * w), Math.round((0.5 - qv.y * 0.5) * h), Math.round(Math.min(maxPx, (2 * qs.x * focal) / depth))]);
364	      }
365	      for (let i = 0; i < nSmall; i++) {
366	        if (sSize[i] <= 0) continue;
367	        qv.fromArray(sPos, i * 3);
368	        const depth = qv.clone().applyMatrix4(camera.matrixWorldInverse).z * -1;
369	        if (depth < 0.1) continue;
370	        qv.project(camera);
371	        if (Math.abs(qv.x) > 1.05 || Math.abs(qv.y) > 1.05) continue;
372	        out.small.push([Math.round((qv.x * 0.5 + 0.5) * w), Math.round((0.5 - qv.y * 0.5) * h), Math.round(Math.min(MAX_PX_SMALL * (h / 1536), (sSize[i] * focal) / depth))]);
373	      }
374	      return out;
375	    },
376	    update(time, dt, focusS, camera, density = 1) {
377	      bigUniforms.uTime.value = time;
378	      ptUniforms.uTime.value = time;
379	      const persp = camera as THREE.PerspectiveCamera;
380	      view.ok = !!persp.isPerspectiveCamera;
381	      if (view.ok) {
382	        camera.updateMatrixWorld();
383	        view.inv.copy(camera.matrixWorldInverse);
384	        camera.getWorldPosition(view.pos);
385	        camera.getWorldDirection(view.dir);
386	        view.right.setFromMatrixColumn(camera.matrixWorld, 0).normalize();
387	        view.up.setFromMatrixColumn(camera.matrixWorld, 1).normalize();
388	        view.tanV = Math.tan(THREE.MathUtils.degToRad(persp.fov) / 2);
389	        view.tanH = view.tanV * persp.aspect;
390	      }
391	      // projected route centre (core lateral at water level) from just ahead of Benny to the far field
392	      coreN = 0;
393	      if (view.ok && focusS >= drumEnd) {
394	        for (let k = 0; k < CORE_N; k++) {
395	          const s = Math.min(course.length, focusS + 1 + k * k * 0.06 + k * 0.5);
396	          course.sample(s, fi);
397	          tmp2.copy(fi.pos).addScaledVector(fi.right, coreLateral(course, s)).addScaledVector(fi.up, 0.05);
398	          const v = tmp2.applyMatrix4(view.inv);
399	          const depth = -v.z;
400	          if (depth < 1) continue;
401	          const yn = v.y / (depth * view.tanV);
402	          if (coreN > 0 && yn <= coreY[coreN - 1]) continue; // keep it monotonic in screen y
403	          coreX[coreN] = v.x / (depth * view.tanH);
404	          coreY[coreN] = yn;
405	          coreN++;
406	        }
407	      }
408	      // pixel scale for impostors and point sprites
409	      const vh = (typeof window !== 'undefined' ? window.innerHeight : 800) * (typeof window !== 'undefined' ? Math.min(2, window.devicePixelRatio || 1) : 1);
410	      const focal = persp.isPerspectiveCamera ? vh / (2 * Math.tan(THREE.MathUtils.degToRad(persp.fov) / 2)) : 600;
411	      const pxK = vh / 1536; // caps are authored for the 864×1536 reference frame
412	      focalNow = focal;
413	      pxKNow = pxK;
414	      // respawn everything after a checkpoint jump / respawn or a camera teleport (the screen-space
415	      // placement needs the camera that will actually show the bubbles)
416	      const camJump = view.ok && lastCam.distanceToSquared(view.pos) > 4;
417	      if (view.ok) lastCam.copy(view.pos);
418	      const jump = Math.abs(focusS - lastFocus) > 25 || (camJump && focusS >= drumEnd);
419	      const crossedDrum = (lastFocus < drumEnd) !== (focusS < drumEnd);
420	      if (jump || crossedDrum) {
421	        rngState = (0x0b0b ^ Math.round(focusS * 16)) >>> 0;
422	        for (const b of bigS) spawn(b, focusS, true, true);
423	        for (const b of smallS) spawn(b, focusS, false, true);
424	      }
425	      lastFocus = focusS;
426	      ptUniforms.uScale.value = focal;
427	      ptUniforms.uMaxPx.value = MAX_PX_SMALL * pxK;
428	      bigUniforms.uFocal.value = focal;
429	      const inDrum = focusS < drumEnd;
430	      bigUniforms.uMaxPx.value = (inDrum ? MAX_PX_DRUM : MAX_PX_RIDE) * pxK;
431	      bigUniforms.uNear.value = inDrum ? 1.2 : 2.6;
432	      const step = (b: BubbleState, isBig: boolean) => {
433	        b.age += dt;
434	        b.pos.addScaledVector(b.vel, dt);
435	        tmp.set(Math.sin(time * 1.3 + b.phase), Math.cos(time * 1.1 + b.phase * 1.7), Math.sin(time * 0.9 + b.phase * 0.6)).multiplyScalar(0.12 * dt);
436	        b.pos.add(tmp);
437	        if (inDrum) {
438	          if (b.age > b.life) spawn(b, focusS, isBig, false);
439	          return;
440	        }
441	        // ride: recycle when passed / out of frame; pop (fast shrink) when drifting into the corridor
442	        const behind = b.s < Math.min(focusS, course.length - 32) - (isBig ? 3 : 2);
443	        const a = allowed(b.pos, isBig ? b.size : 0);
444	        if (behind || a < 0 || b.age > b.life) spawn(b, focusS, isBig, false);
445	        else if (a === 0) b.life = Math.min(b.life, b.age + 0.25);
446	      };
447	      const bigLimit = Math.round((inDrum ? Math.min(nBig, 16) : ride.big) * density);
448	      const smallLimit = Math.round((inDrum ? nSmall * 0.95 : ride.small) * density);
449	      for (let i = 0; i < nBig; i++) {
450	        const b = bigS[i];
451	        step(b, true);
452	        const pop = i < bigLimit ? Math.min(1, b.age * 1.5, (b.life - b.age) * 2) : 0;
453	        const sz = b.size * Math.max(0, pop) * (1 + 0.04 * Math.sin(time * 4 + b.phase));
454	        scl.set(sz, sz, sz);
455	        tmpM.compose(b.pos, one, scl);
456	        big.setMatrixAt(i, tmpM);
457	      }
458	      big.instanceMatrix.needsUpdate = true;
459	      for (let i = 0; i < nSmall; i++) {
460	        const b = smallS[i];
461	        step(b, false);
462	        b.pos.toArray(sPos, i * 3);
463	        sSize[i] = i < smallLimit ? b.size * Math.max(0, Math.min(1, b.age * 3, (b.life - b.age) * 3)) : 0;
464	      }
465	      (pGeo.attributes.position as THREE.BufferAttribute).needsUpdate = true;
466	      (pGeo.attributes.aSize as THREE.BufferAttribute).needsUpdate = true;
467	    },
468	  };
469	}
